const activeGMs = game.users.filter(u => u.active && u.isGM).sort((a,b) => a.id.localeCompare(b.id));
if (!activeGMs.length || game.user.id !== activeGMs[0].id) return;
const token = event?.data?.token;
if (!token?.actor) return;
const actor = token.actor;
const state = foundry.utils.deepClone(actor.getFlag("world","dicebox") ?? {});
state.centralLodge ??= {}; state.centralLodge.f2 ??= {};
if (state.centralLodge.f2.eastAnchorSeen === true) return;
state.centralLodge.f2.eastAnchorSeen = true; state.centralLodge.f2.eastAnchorSeenAt = Date.now();
await actor.setFlag("world","dicebox",state);
const recipients = [...new Set([event?.user?.id, ...activeGMs.map(u => u.id)].filter(Boolean))];
await ChatMessage.create({content:`<p>The eastern station carries the same load as the western one, feeding the chamber through separate channels. It is part of the working rite, not decoration.</p>`,whisper:recipients});

